diff --git a/mailnews/addrbook/modules/AddrBookCard.sys.mjs b/mailnews/addrbook/modules/AddrBookCard.sys.mjs
index 3310fc0d083..57a40b7e9e2 100644
--- a/mailnews/addrbook/modules/AddrBookCard.sys.mjs
+++ b/mailnews/addrbook/modules/AddrBookCard.sys.mjs
@@ -436,24 +436,6 @@ AddrBookCard.prototype = {
       this.getProperty("PhoneticLastName", "")
     );
   },
-  generateChatName() {
-    for (const name of [
-      "_GoogleTalk",
-      "_AimScreenName",
-      "_Yahoo",
-      "_Skype",
-      "_QQ",
-      "_MSN",
-      "_ICQ",
-      "_JabberId",
-      "_IRC",
-    ]) {
-      if (this._properties.has(name)) {
-        return this._properties.get(name);
-      }
-    }
-    return "";
-  },
   copy() {
     throw Components.Exception(
       "nsIAbCard.copy() not implemented",
diff --git a/mailnews/addrbook/public/nsIAbCard.idl b/mailnews/addrbook/public/nsIAbCard.idl
